            tokenEnv: stringFlag(args, 'token-env', 'TAKU_BEARER_TOKEN'),
            host: stringFlag(args, 'host', 'all'),
            maxProjects: numberFlag(args, 'max-projects', 20),
            maxSessionFiles: numberFlag(args, 'max-session-files', 200),
